sheets.ai:
.fz { color-scheme: light; }
body { margin: 0px; padding: 0px; font: 14px -apple-system, BlinkMacSystemFont, sans-serif; background: rgb(255, 255, 255); color: rgb(0, 0, 0); }
body { background: var(--c-bg-app); color: var(--c-text); font: 400 14px/1.55 var(--f-ui); padding-left: max(16px,env(safe-area-inset-left,0px)); padding-right: max(16px,env(safe-area-inset-right,0px)); padding-block: 28px 64px; }
.ph { display: flex; flex-wrap: wrap; gap: 16px 32px; align-items: flex-end; justify-content: space-between; }
.ai { width: 360px; flex: 0 0 auto; }
.thread { flex: 1 1 0%; min-height: 0px; overflow: hidden; padding: 12px; display: flex; flex-direction: column; gap: 14px; }
.askq { align-self: flex-end; max-width: 88%; background: var(--c-bg-active); border-radius: 8px; padding: 8px 10px; }
.sends { font-size: 12px; line-height: 16px; color: var(--c-text-muted); display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; }
.sends .si { display: inline-flex; align-items: center; gap: 4px; color: var(--c-text); }
.sends .lnk { color: var(--c-accent-text); font-weight: 600; }
.compose { border-top: 1px solid var(--c-border-subtle); padding: 10px 12px 12px; display: flex; flex-direction: column; gap: 8px; }
.ta { min-height: 64px; border-top-color: ; border-top-style: ; border-top-width: ; border-right-color: ; border-right-style: ; border-right-width: ; border-left-color: ; border-left-style: ; border-left-width: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-bottom: 2px solid var(--c-accent); border-radius: 4px; background: var(--c-bg-surface); padding: 6px 8px; display: flex; flex-direction: column; justify-content: space-between; }
.ta .ph { color: var(--c-text-faint); }
@media (max-width: 640px){
body { padding-block: 20px 48px; }
}
html { scroll-behavior: smooth; }
.inp.bad { border-bottom: 2px solid var(--c-danger-solid); }
.ferr { font-size: 12px; line-height: 16px; color: var(--c-danger-text); display: flex; align-items: center; gap: 6px; }
.desk { width: 1280px; height: 800px; }
.phd { height: 44px; flex: 0 0 auto; display: flex; align-items: center; gap: 8px; padding: 0px 6px 0px 12px; }
.phd b { font: 600 15px/20px var(--f-disp); }
.flt { padding: 0px 8px 6px; flex: 0 0 auto; }
.tr.conn { font-weight: 600; }
.tr .chip.prod { height: 18px; font-size: 11px; }
.tr.sqh { margin-top: 8px; }
.rtab { gap: 6px; }
.lt td .dbi { vertical-align: -3px; }
.lt td .chip.prod { height: 16px; font-size: 10px; padding: 0px 4px; border-radius: 3px; letter-spacing: 0.04em; }
.cxr { display: flex; flex-wrap: wrap; gap: 4px; padding: 8px 12px 0px; flex: 0 0 auto; }
.cxr .chip .ico, .cxr .chip .dbi { flex: 0 0 auto; }
.thread { gap: 12px; }
.thread > * { flex: 0 0 auto; }
.ctxl { display: flex; align-items: center; gap: 6px; font-size: 12px; line-height: 16px; color: var(--c-text-muted); min-width: 0px; }
.ctxl > .ico { flex: 0 0 auto; color: var(--c-text-subtle); }
.ctxl .t { min-width: 0px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ctxl .lnk { flex: 0 0 auto; }
.sends .b { color: var(--c-text-subtle); font-variant-numeric: tabular-nums; margin-left: 2px; }
.sends .si.lk { color: var(--c-text-faint); }
.tarow { display: flex; align-items: center; gap: 6px; }
.ta.off { border-bottom-color: var(--c-border-strong); }
.ta.off .ph { color: var(--c-text-faint); }
.btn.pri.dis { background: var(--c-bg-active); color: var(--c-text-faint); }
.errc { border-radius: 6px; padding: 10px 12px; display: flex; flex-direction: column; gap: 8px; background: var(--c-danger-subtle); }
.errc.warn { background: var(--c-warning-subtle); }
.errc .eh { display: flex; gap: 8px; align-items: flex-start; color: var(--c-text); font-weight: 600; }
.errc .eh > .ico { flex: 0 0 auto; margin-top: 1px; color: var(--c-danger-text); }
.errc.warn .eh > .ico { color: var(--c-warning-text); }
.errc .ed { font-size: 12px; line-height: 16px; color: var(--c-text-muted); padding-left: 24px; }
.errc .em { font: 11px/16px var(--f-code); color: var(--c-text-subtle); padding-left: 24px; }
.errc .row { padding-left: 24px; gap: 6px; }
.errc .btn.sec.dis { background: var(--c-bg-active); border-color: var(--c-border); color: var(--c-text-faint); }
.thread .empty2 { padding: 24px 8px; }
.thread .ebox2 .btn { flex: 0 0 auto; }
.ban b { font-weight: 600; }
.ban.top { align-items: flex-start; }
.ban.top > .ico { margin-top: 1px; }
.setw { flex-direction: row; }
.snav2 { width: 196px; flex: 0 0 auto; background: var(--c-bg-panel); border-right: 1px solid var(--c-border-subtle); padding: 8px 0px; display: flex; flex-direction: column; gap: 2px; }
.snav2 .flt { padding: 0px 8px 6px; }
.it2 { height: 28px; display: flex; align-items: center; gap: 8px; padding: 0px 10px 0px 12px; position: relative; margin: 0px 6px; border-radius: 4px; color: var(--c-text); white-space: nowrap; }
.it2 .ico { color: var(--c-text-muted); }
.it2.sub { padding-left: 36px; color: var(--c-text-muted); }
.it2.sel { background: var(--c-accent-subtle); color: var(--c-text); }
.it2.sel::before { content: ""; position: absolute; left: 0px; top: 6px; width: 2px; height: 16px; border-radius: 2px; background: var(--c-accent); }
.smain { flex: 1 1 0%; min-width: 0px; min-height: 0px; overflow: hidden; padding: 18px 22px; display: flex; flex-direction: column; gap: 14px; }
.smain .hhd { gap: 12px; align-items: baseline; }
.smain .hhd h3 { font: 600 20px/28px var(--f-disp); margin: 0px; }
.scols { display: grid; grid-template-columns: minmax(0px, 1fr) minmax(0px, 1fr); gap: 0px 24px; min-height: 0px; }
.ssec { display: flex; flex-direction: column; gap: 10px; padding: 12px 0px 14px; border-top: 1px solid var(--c-border-subtle); }
.ssec:first-child { border-top: 0px; padding-top: 0px; }
.stitle { font: 600 14px/20px var(--f-disp); display: flex; align-items: center; gap: 8px; }
.swrow { display: grid; grid-template-columns: 40px minmax(0px, 1fr); gap: 2px 12px; align-items: center; padding: 4px 0px; }
.swrow .t { font-weight: 600; }
.swrow .d { grid-column: 2; font-size: 12px; line-height: 16px; color: var(--c-text-subtle); }
.track.on::after { left: auto; right: 3px; background: var(--on-accent); }
.lt.c32 td { height: 32px; }
.lt .tsel { font-family: var(--f-ui); font-size: 12px; }
.mx th, .mx td { text-align: center; }
.mx th:first-child, .mx td:first-child { text-align: left; white-space: normal; }
.mx td { height: 30px; font-size: 12px; line-height: 16px; }
.mx td .ico { vertical-align: -3px; }
.mx .y { color: var(--c-success-text); }
.mx .no { color: var(--c-text-faint); }
.mx .pa { color: var(--c-warning-text); font-weight: 600; }
.mx th { white-space: normal; line-height: 14px; vertical-align: bottom; padding-top: 6px; padding-bottom: 6px; height: auto; }
.ptiles { display: grid; grid-template-columns: repeat(5, minmax(0px, 1fr)); gap: 8px; }
.ptile { border: 1px solid var(--c-border); border-radius: 6px; background: var(--c-bg-surface); padding: 8px 10px; display: flex; flex-direction: column; gap: 4px; min-width: 0px; }
.ptile.on { border-color: var(--c-accent); box-shadow: inset 0 0 0 1px var(--c-accent); }
.ptile .pn2 { display: flex; align-items: center; gap: 8px; font-weight: 600; white-space: nowrap; }
.ptile .pn2 .radio { height: 16px; }
.ptile .ps { font-size: 12px; line-height: 16px; color: var(--c-text-subtle); }
.ptile .chip { align-self: flex-start; height: 18px; }
.fgrid { display: grid; grid-template-columns: minmax(0px, 1fr) minmax(0px, 1fr); gap: 12px; }
.fgrid.one { grid-template-columns: minmax(0px, 1fr); }
.fgrid.three { grid-template-columns: minmax(0px, 1fr) minmax(0px, 1fr) minmax(0px, 1fr); }
.inp .suf { color: var(--c-text-subtle); font: 12px/16px var(--f-ui); }
.inp .ico { color: var(--c-text-subtle); }
.inp .ph2 { color: var(--c-text-faint); font-family: var(--f-ui); }
.trow { display: flex; align-items: center; gap: 10px; font-size: 12px; line-height: 16px; }
.trow .okt, .trow .badt { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; }
.hint .ico, .ferr .ico { flex: 0 0 auto; }
.hint.row2 { display: flex; gap: 6px; align-items: flex-start; }
.ptile .pn2 { white-space: normal; align-items: flex-start; line-height: 16px; }
.ptile .pn2 .radio { flex: 0 0 auto; }
.body:has(> .ai) .col .strip > .chip[title^="AI access"] { display: none; }
.lt .tsel { max-width: 200px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.scols.wide1 { grid-template-columns: minmax(0px, 1.15fr) minmax(0px, 1fr); }
